head.script:
scwin.isWithinPercent = function(checkValue, baseValue, percentage) {
	const margin = baseValue * (percentage / 100);
	return (checkValue >= baseValue - margin) && (checkValue <= baseValue + margin);
};

scwin.checkVal = function() {
	// level0 대구광역시(c22) 영역 크기 - 군위군 편입으로 세로로 긴 형태 (dataMapRatio 별 simp01 / simp1 / simp16)
	const expected = [[31.2, 54.29], [32.98, 53.71], [33.35, 54.01]];
	for (let i = 0; i < expected.length; i++) {
		const map = document.getElementById("mf_mapchart" + (i + 1) + "_map") || document.getElementById("mapchart" + (i + 1) + "_map");
		const pathData = map && map.querySelector("path.c22");
		if (!pathData) {
			return false;
		}
		const bbox = pathData.getBBox();
		if (!(scwin.isWithinPercent(bbox.width, expected[i][0], 2) && scwin.isWithinPercent(bbox.height, expected[i][1], 2))) {
			return false;
		}
	}
	return true;
};

// level1 지도 변경 (level1 지도 파일은 simp1 만 있으므로 mapchart1·mapchart2)
scwin.changeLevel1 = function(code) {
	mapchart1.changeMap(code);
	mapchart2.changeMap(code);
};

// 현재 지도에 그려진 지역 코드 목록
scwin.getCodes = function(id) {
	const map = document.getElementById("mf_" + id + "_map") || document.getElementById(id + "_map");
	const codes = [];
	map.querySelectorAll("path.municipality").forEach(function(p) {
		codes.push(p.getAttribute("class").replace("municipality c", ""));
	});
	return codes.join(",");
};
